style.css:
@-moz-document domain("spotify.com") {
/* Achtergrond overal */
html, body, #main, .Root,
.main-view-container,
.main-view-container__scrollable,
.main-view-container__content,
.main-home,
.main-home-content,
main {
  background-color: #080a12 !important;
  background-image: linear-gradient(135deg, #080a12, #171025, #080a12) !important;
}

/* Hoofdvenster */
.main-view-container {
  background: #090b14 !important;
}

/* Zijbalk en bibliotheek */
.main-sidebar,
.main-yourLibraryX,
.main-yourLibraryX-contents,
.main-yourLibraryX-header,
.main-yourLibraryX-library {
  background: #10121d !important;
}

/* Bovenbalk */
.main-topBar,
.main-topBar-background {
  background: #0a0c16 !important;
}

/* Kaarten */
.main-card-card {
  background: #171a29 !important;
}

/* Muziekbalk */
.main-nowPlayingBar-container,
.main-nowPlayingBar {
  background: #090b14 !important;
}

/* Paarse accenten */
button,
a,
.progress-bar {
  accent-color: #a66aff !important;
}

/* Scrollbalk */
::-webkit-scrollbar-thumb {
  background: #7544bb !important;
}
}
